 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return [row[:] for row in grid]

    # The open field is the most frequent color. Fill enclosed regions of
    # that color according to the color of the enclosing frame.
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            boundary = Counter()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        v = grid[yy][xx]
                        if v == background:
                            if (yy, xx) not in seen:
                                seen.add((yy, xx))
                                q.append((yy, xx))
                        else:
                            boundary[v] += 1
            if not touches_edge and boundary:
                frame = boundary.most_common(1)[0][0]
                fill = 2 if frame == 6 else 7
                for y, x in cells:
                    out[y][x] = fill
    return out


def _self_test():
    # Compact fixture checks: enclosed center in a small frame, and a larger
    # frame whose color selects fill 2.
    a = [[9]*5 for _ in range(5)]
    for c in range(1, 4):
        a[1][c] = a[3][c] = 3
    a[2][1] = a[2][3] = 3
    assert transform(a)[2][2] == 7
    b = [[9]*8 for _ in range(8)]
    for r in range(1, 7):
        b[r][1] = b[r][6] = 6
    for c in range(1, 7):
        b[1][c] = b[6][c] = 6
    assert all(transform(b)[r][c] == 2 for r in range(2, 6) for c in range(2, 6))


if __name__ == '__main__':
    _self_test()
    print('self-test passed')
